(function(root){
'use strict';
const E=root.FlowerEngine;
function poly(ctx,points){ctx.beginPath();ctx.moveTo(points[0],points[1]);for(let i=2;i<points.length;i+=2)ctx.lineTo(points[i],points[i+1]);ctx.closePath();}
function hex(h,n){const c=h.replace('#','');return '#'+[0,2,4].map(i=>Math.max(0,Math.min(255,parseInt(c.slice(i,i+2),16)+n)).toString(16).padStart(2,'0')).join('');}
class ClothRenderer{
 constructor(canvas,getState){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.getState=getState;this.patterns=new Map();this.time=0;this.hover=null;this.drag=null;this.placedAt={};this.lastChapter=-1;this.matrix=null;this.w=0;this.h=0;this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(canvas);this.resize();this.active=true;this.loop=this.loop.bind(this);requestAnimationFrame(this.loop);}
 resize(){const b=this.canvas.getBoundingClientRect();this.w=Math.max(1,b.width);this.h=Math.max(1,b.height);this.dpr=Math.min(devicePixelRatio||1,2);this.canvas.width=Math.round(this.w*this.dpr);this.canvas.height=Math.round(this.h*this.dpr);this.patterns.clear();}
 texture(ctx,color){let p=this.patterns.get(color);if(p)return p;const c=document.createElement('canvas');c.width=c.height=96;const t=c.getContext('2d'),rand=E.seeded(parseInt(color.slice(1),16));t.fillStyle=color;t.fillRect(0,0,96,96);for(let x=0;x<96;x++){t.strokeStyle=x%3===0?'rgba(255,242,217,.10)':'rgba(0,0,0,.13)';t.lineWidth=.6+rand()*.6;t.beginPath();t.moveTo(x+.2,0);t.lineTo(x+.2,96);t.stroke();}for(let y=0;y<96;y++){t.strokeStyle=y%3===0?'rgba(255,239,219,.11)':'rgba(0,0,0,.15)';t.lineWidth=.5+rand()*.8;t.beginPath();t.moveTo(0,y+.3);t.lineTo(96,y+.3);t.stroke();}for(let i=0;i<320;i++){t.fillStyle=rand()>.5?'rgba(255,235,206,.10)':'rgba(0,0,0,.13)';t.fillRect(rand()*96,rand()*96,.7,1.4);}p=ctx.createPattern(c,'repeat');this.patterns.set(color,p);return p;}
 cloth(ctx,pts,color,seed=1,shadow=true){ctx.save();if(shadow){ctx.shadowColor='rgba(0,0,0,.65)';ctx.shadowBlur=5;ctx.shadowOffsetX=1.5;ctx.shadowOffsetY=3.5;}poly(ctx,pts);ctx.fillStyle=this.texture(ctx,color);ctx.fill();ctx.shadowColor='transparent';ctx.clip();const bounds={minX:Math.min(...pts.filter((_,i)=>!(i%2))),maxX:Math.max(...pts.filter((_,i)=>!(i%2))),minY:Math.min(...pts.filter((_,i)=>i%2)),maxY:Math.max(...pts.filter((_,i)=>i%2))};const g=ctx.createLinearGradient(bounds.minX,bounds.minY,bounds.maxX,bounds.maxY);g.addColorStop(0,'rgba(255,237,204,.12)');g.addColorStop(.3,'rgba(255,255,255,.02)');g.addColorStop(1,'rgba(0,0,0,.25)');ctx.fillStyle=g;ctx.fillRect(bounds.minX-1,bounds.minY-1,bounds.maxX-bounds.minX+2,bounds.maxY-bounds.minY+2);ctx.restore();ctx.save();poly(ctx,pts);ctx.strokeStyle=hex(color,28);ctx.globalAlpha=.65;ctx.lineWidth=.7;ctx.stroke();const rand=E.seeded(seed*7109);for(let j=0;j<pts.length;j+=2){const nx=pts[(j+2)%pts.length],ny=pts[(j+3)%pts.length],x=pts[j],y=pts[j+1];for(let k=0;k<9;k++){const a=rand(),xx=E.mix(x,nx,a),yy=E.mix(y,ny,a);ctx.strokeStyle='rgba(218,198,170,.24)';ctx.lineWidth=.35;ctx.beginPath();ctx.moveTo(xx,yy);ctx.quadraticCurveTo(xx+rand()*3-1,yy-2-rand()*2,xx+rand()*3-1,yy-3-rand()*2);ctx.stroke();}}ctx.restore();}
 drawBase(ctx,s){ctx.save();ctx.shadowColor='rgba(0,0,0,.6)';ctx.shadowBlur=25;ctx.shadowOffsetY=18;
 this.cloth(ctx,[-130,-232,-151,-244,-231,-359,-245,-343,-166,-183,-132,-184],'#243a40',1);
 this.cloth(ctx,[130,-232,151,-244,231,-359,245,-343,166,-183,132,-184],'#243a40',2);
 this.cloth(ctx,[-96,230,-56,239,-72,342,-101,326],'#293c42',3);
 this.cloth(ctx,[96,230,56,239,72,342,101,326],'#293c42',4);
 const pts=[-133,-248,133,-248,161,-207,155,227,104,273,-104,273,-155,227,-161,-207];
 this.cloth(ctx,pts,'#1d3036',4);ctx.shadowColor='transparent';
 ctx.lineWidth=.7;ctx.strokeStyle='#947e65';ctx.setLineDash([2,3]);ctx.strokeRect(-142,-226,284,458);ctx.setLineDash([]);
 this.cloth(ctx,[-132,-217,132,-217,132,226,-132,226],'#23383c',6,false);
 this.border(ctx,s);ctx.restore();}
 border(ctx,s){const c=E.palette;ctx.save();ctx.globalAlpha=.75;for(let y=-201;y<219;y+=18){for(const side of [-1,1]){const x=side*143;ctx.strokeStyle=y%36===-21?c.red:c.gold;ctx.lineWidth=1;poly(ctx,[x,y-4,x+4,y,x,y+4,x-4,y]);ctx.stroke();}}for(let x=-124;x<=124;x+=15){ctx.strokeStyle=c.gold;ctx.beginPath();ctx.moveTo(x,-234);ctx.lineTo(x+5,-228);ctx.lineTo(x+10,-234);ctx.stroke();ctx.beginPath();ctx.moveTo(x,241);ctx.lineTo(x+5,247);ctx.lineTo(x+10,241);ctx.stroke();}
 if(s.chapter>=4){ctx.strokeStyle=c.cream;ctx.globalAlpha=.75;ctx.lineWidth=.9;for(let x=-116;x<118;x+=s.wish==='安稳'?18:s.wish==='陪伴'?24:16){ctx.beginPath();if(s.wish==='安稳'){ctx.moveTo(x,256);ctx.lineTo(x+9,256);}else if(s.wish==='陪伴'){ctx.arc(x,256,3,0,Math.PI*2);ctx.moveTo(x+8,256);ctx.arc(x+8,256,3,0,Math.PI*2);}else{ctx.moveTo(x,259);ctx.lineTo(x+6,251);ctx.lineTo(x+12,255);}ctx.stroke();}}ctx.restore();}
 piece(ctx,p,alpha=1){ctx.save();ctx.globalAlpha=alpha;this.cloth(ctx,p.points,p.fill,p.index+10);const pts=p.points;ctx.strokeStyle='rgba(25,12,11,.35)';ctx.lineWidth=1.7;ctx.beginPath();ctx.moveTo(pts[0],pts[1]);ctx.lineTo(pts[4],pts[5]);ctx.stroke();ctx.strokeStyle='rgba(240,220,182,.16)';ctx.lineWidth=.55;ctx.beginPath();ctx.moveTo(pts[0]+.7,pts[1]);ctx.lineTo(pts[4]+.7,pts[5]);ctx.stroke();ctx.restore();}
 foldScene(ctx,s){const p=E.pieces.find(p=>p.id==='p07'),pts=p.points,A=[pts[2],pts[3]],C=[pts[4],pts[5]],B=[pts[0],pts[1]],D=[-B[0],B[1]];ctx.save();ctx.translate(-p.centroid[0],-p.centroid[1]);this.cloth(ctx,[...A,...B,...C],p.fill,45);const t=s.fold,yy=E.mix(D[1],B[1],t),xx=E.mix(D[0],B[0],t);ctx.save();ctx.shadowColor='rgba(0,0,0,.75)';ctx.shadowBlur=4+14*Math.sin(t*Math.PI);ctx.shadowOffsetX=9*Math.sin(t*Math.PI);this.cloth(ctx,[...A,xx,yy,...C],t<.5?hex(p.fill,-10):hex(p.fill,5),46);ctx.restore();ctx.lineWidth=.35;ctx.setLineDash([1,1.5]);ctx.strokeStyle='rgba(234,218,184,.52)';ctx.beginPath();ctx.moveTo(...A);ctx.lineTo(...C);ctx.stroke();ctx.setLineDash([]);ctx.restore();}
 renderTo(ctx,w,h,s,time=0,exporting=false){ctx.clearRect(0,0,w,h);const base=Math.min(w/450,h/690),chapter=s.chapter;let zoom=1,focus=[0,-8];if(chapter===1){zoom=3.65;focus=[0,0];}else if(chapter===2){zoom=1.18;focus=[0,8];}else if(s.scale==='macro'){zoom=4.1;focus=E.pieces[6].centroid;}else if(s.scale==='pattern'){zoom=1.25;focus=[0,-3];}
 const sway=s.reduced||chapter===2||chapter===1||exporting?0:Math.sin(time*.00025)*.012;
 ctx.save();ctx.translate(w*.5,h*.5);ctx.scale(base*zoom,base*zoom);ctx.rotate((s.angle||0)*Math.PI/180+sway);ctx.translate(-focus[0],-focus[1]);if(!exporting)this.matrix=ctx.getTransform();
 if(chapter===1)this.foldScene(ctx,s);else{this.drawBase(ctx,s);const showAll=chapter!==2&&s.composition==='design';const ids=new Set(showAll?E.pieces.map(p=>p.id):E.visible(s));for(const p of E.pieces){if(ids.has(p.id)){const at=this.placedAt[p.id]||0;const age=time-at;let a=1;if(!s.reduced&&age>=0&&age<500&&chapter===2)a=.4+.6*Math.min(1,age/500);this.piece(ctx,p,a);}else if(chapter===2){ctx.save();poly(ctx,p.points);ctx.fillStyle=p.id===s.selected?'rgba(212,187,147,.14)':'rgba(190,177,148,.025)';ctx.fill();ctx.strokeStyle=p.id===s.selected?'rgba(223,199,159,.7)':'rgba(183,170,145,.15)';ctx.lineWidth=p.id===s.selected?1.1:.45;ctx.setLineDash(p.id===s.selected?[2,2]:[]);ctx.stroke();ctx.restore();}}
 if(chapter===2&&this.drag){const p=E.pieces.find(p=>p.id===this.drag.id);ctx.save();ctx.translate(this.drag.x-p.centroid[0],this.drag.y-p.centroid[1]);this.piece(ctx,p,.95);ctx.restore();}
 if(chapter===3&&!exporting){const p=E.pieces[6],c=p.centroid;ctx.save();ctx.strokeStyle='rgba(224,204,164,.65)';ctx.lineWidth=.6;ctx.beginPath();ctx.arc(c[0],c[1],11,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(c[0]+13,c[1]);ctx.lineTo(c[0]+45,c[1]-20);ctx.lineTo(c[0]+95,c[1]-20);ctx.stroke();ctx.fillStyle='#d7c4a4';ctx.font='7px Georgia';ctx.fillText('P07',c[0]+64,c[1]-24);ctx.restore();}}
 ctx.restore();}
 loop(time){if(!this.active)return;this.time=time;this.ctx.setTransform(this.dpr,0,0,this.dpr,0,0);this.renderTo(this.ctx,this.w,this.h,this.getState(),time);requestAnimationFrame(this.loop);}
 localPoint(clientX,clientY){if(!this.matrix)return [0,0];const r=this.canvas.getBoundingClientRect();const p=new DOMPoint((clientX-r.left)*this.dpr,(clientY-r.top)*this.dpr).matrixTransform(this.matrix.inverse());return [p.x,p.y];}
 target(id){const p=E.pieces.find(p=>p.id===id),v=new DOMPoint(...p.centroid).matrixTransform(this.matrix);const r=this.canvas.getBoundingClientRect();return {x:r.left+v.x/this.dpr,y:r.top+v.y/this.dpr};}
 markPlaced(id){this.placedAt[id]=performance.now();}
 renderCard(s){const c=document.createElement('canvas');c.width=1600;c.height=2000;const ctx=c.getContext('2d');ctx.fillStyle='#111c22';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='#7c6b55';ctx.strokeRect(58,58,1484,1884);ctx.fillStyle='#ae9671';ctx.font='22px Georgia';ctx.textAlign='center';ctx.fillText('A WISH, IN EVERY FOLD',800,137);ctx.fillStyle='#e5d6b6';ctx.font='76px "Noto Serif SC","Songti SC",SimSun,serif';ctx.fillText('背上的花',800,250);this.renderToPreserved(ctx,230,320,1140,1320,{...s,chapter:4,scale:'whole',angle:0,reduced:true});ctx.textAlign='center';ctx.fillStyle='#d9c5a1';ctx.font='32px "Microsoft YaHei",sans-serif';ctx.fillText('愿 · '+s.wish,800,1610);ctx.fillStyle='#a99b80';ctx.font='19px \"Microsoft YaHei\",sans-serif';ctx.fillText(s.composition==='design'?'完整设计参考':'我的叠放 · '+s.placed.length+' / 24 片',800,1562);ctx.fillStyle='#d7cdbb';ctx.font='27px "Microsoft YaHei",sans-serif';const chars=Array.from(s.message),lines=[];for(let i=0;i<chars.length;i+=22)lines.push(chars.slice(i,i+22).join(''));lines.forEach((line,i)=>ctx.fillText(line,800,1680+i*44));ctx.fillStyle='#a79e8a';ctx.font='18px "Microsoft YaHei",sans-serif';ctx.fillText('当代原创艺术演绎 · 非馆藏复刻 · 当代祝愿非传统纹样释义',800,1840);ctx.fillText('研究入口：中央民族大学民族博物馆《母亲背上的摇篮——背孩带》',800,1876);return c;}
 renderToPreserved(ctx,x,y,w,h,s){const layer=document.createElement('canvas');layer.width=w;layer.height=h;this.renderTo(layer.getContext('2d'),w,h,s,0,true);ctx.drawImage(layer,x,y);}
}
root.ClothRenderer=ClothRenderer;
})(window);
